    }
    policer CRITICAL {
        filter-specific;
        if-exceeding {
            bandwidth-limit 4m;
            burst-size-limit 1500;
        }
        then discard;
    }
    policer IMPORTANT {
        filter-specific;
        if-exceeding {
            bandwidth-limit 512k;
